static int rtl_s5_wol(struct r8152 *tp)
{
	struct usb_device *udev = tp->udev;
	u32 ocp_data;
	int ret;

	if (!tp->saved_wolopts)
		return -EOPNOTSUPP;

	switch (tp->version) {
	case RTL_VER_01:
	case RTL_VER_02:
	case RTL_VER_07:
		return -EOPNOTSUPP;
	case RTL_VER_03:
	case RTL_VER_04:
	case RTL_VER_05:
	case RTL_VER_06:
		goto remote_wake;
	default:
		break;
	}

	ret = ocp_read_word(tp, MCU_TYPE_PLA, PLA_CONFIG5, &ocp_data);
	if (ret < 0)
		goto out;
	if (!(ocp_data & LAN_WAKE_EN))
		return -EOPNOTSUPP;

	ret = ocp_byte_set_bits(tp, MCU_TYPE_PLA, PLA_INDICATE_FALG, BIT(1));
	if (ret < 0)
		goto out;

